SET DEFINE OFF
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
DECLARE v_cnt PLS_INTEGER; BEGIN
    SELECT COUNT(*) INTO v_cnt FROM MODEL_REGISTRY WHERE MODEL_VERSION = 'LGBM-BASE-0.3';
    IF v_cnt <> 1 THEN RAISE_APPLICATION_ERROR(-20202, 'MODEL_REGISTRY에 LGBM-BASE-0.3 행이 없습니다.'); END IF;
    SELECT COUNT(*) INTO v_cnt FROM APP_USER WHERE DUMMY_YN = 'Y' AND ROLE_CODE = 'ROLE_USER' AND WORK_PERIOD_MONTHS IS NOT NULL;
    IF v_cnt <> 400 THEN RAISE_APPLICATION_ERROR(-20203, '시드 회원 400명이 아니거나 근무기간이 비어 있습니다. update_seed_user_work_period.sql을 먼저 실행하세요.'); END IF;
END;
